 const width=680,height=230,L=52,R=14,T=20,B=33,lo0=Math.min(...all.map(p=>p.value),reference??Infinity),hi0=Math.max(...all.map(p=>p.value),reference??-Infinity),pad=(hi0-lo0||Math.abs(hi0)*.05||1)*.12,lo=lo0-pad,hi=hi0+pad,x=d=>L+(Date.parse(d)-Date.parse(start))/(Date.parse(end)-Date.parse(start)||1)*(width-L-R),y=v=>T+(hi-v)/(hi-lo)*(height-T-B),ex=x(event().date);let chart=`<svg class="hf-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${E(title)}"><title>${E(title)}</title><desc>${E(list.map(s=>s.name+' in '+s.unit).join('; '))}. ${S.mode==='latest'?'Latest lookback; no historical event marker.':'Violet dashed line is the '+E(event().dateKind)+' on '+event().date+'.'} Data to cursor ${E(S.cursor)}. Observation tables below.</desc><rect x="${L}" y="${T}" width="${width-L-R}" height="${height-T-B}" fill="#f6f6f0"/>`;
