 function shareChips(){const records=S.shares.map(id=>data.records.find(r=>r.id===id)).filter(Boolean);$('#hf-selected-shares').innerHTML='<span class="hf-label">Selected listings</span>'+records.map(r=>{const ticker=r.ticker||r.bbTicker?.split(' ')[0]||r.id,logo=window.CompanyLogos?.data?CompanyLogos.html([ticker],CompanyLogos.data):'';return `<span class="hf-share-chip">${logo||'<span class="hf-logo-initial">'+E(ticker.slice(0,4))+'</span>'}<span><b>${E(ticker)}</b> · ${E(r.currency)}<small>${E(r.bbTicker||r.exchange||r.id)}</small></span><button data-remove-share="${E(r.id)}" aria-label="Remove ${E(r.name)}">×</button></span>`;}).join('')+'<button id="hf-basket">'+(S.mode==='latest'?'Use watchlist quick set':'Use event research basket')+'</button><span class="hf-meta">Maximum four · exact listing / currency · raw price paths</span>';for(const img of $('#hf-selected-shares').querySelectorAll('img'))img.addEventListener('error',()=>{img.hidden=true;img.nextElementSibling.hidden=false;},{once:true});$('#hf-basket').onclick=async()=>{const candidates=S.mode==='latest'?data.watchlist.slice(0,4).map(w=>w.record):event().suggestedShareBasket.map(t=>data.records.find(r=>r.bbTicker===t)).filter(Boolean),hs=await Promise.all(candidates.map(r=>D.share(r.id))),b=bounds(),chosen=candidates.filter((r,i)=>hs[i]&&[...hs[i].price.points,...hs[i].pe.points].some(p=>p.date>=b.start&&p.date<=b.end)).slice(0,4);if(S.mode==='latest'){S.shares=candidates.map(r=>r.id);render();return;}if(chosen.length){S.shares=chosen.map(r=>r.id);render();}else status('No exact suggested listing has saved price or P/E in this event window; existing selection retained.');};}
